-- Read-only post-migration/post-test evidence. No patient values returned.
SELECT jsonb_build_object(
 'operator',current_user,
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',r.rolname,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'backendDirect',has_table_privilege('dental_backend',c.oid,'SELECT,INSERT,UPDATE,DELETE')) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='dental' AND c.relkind='r'),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'signature',pg_get_function_identity_arguments(p.oid),'owner',r.rolname,'definer',p.prosecdef,'settings',p.proconfig,'backendExecute',has_function_privilege('dental_backend',p.oid,'EXECUTE'),'operatorExecute',has_function_privilege('postgres',p.oid,'EXECUTE')) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname='dental'),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',parent.rolname,'member',member.rolname,'grantor',grantor.rolname,'grantorSuper',grantor.rolsuper,'admin',m.admin_option,'set',to_jsonb(m)->'set_option','inherit',to_jsonb(m)->'inherit_option')),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles member ON member.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor WHERE parent.rolname IN('dental_backend','dental_function_owner') OR member.rolname IN('dental_backend','dental_function_owner')),
 'privateRows',jsonb_build_object('accounts',(SELECT count(*) FROM dental.accounts),'patients',(SELECT count(*) FROM dental.patients),'appointments',(SELECT count(*) FROM dental.appointments),'audit',(SELECT count(*) FROM dental.audit_events)),
 'browserSchemaAccess',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'usage',has_schema_privilege(oid,'dental','USAGE'),'create',has_schema_privilege(oid,'dental','CREATE')) ORDER BY rolname) FROM pg_roles WHERE rolname IN('anon','authenticated','authenticator','service_role'))
) AS task3_state;
